	function handleAttachmentsDisciplinare(selectObj) {
		if (selectObj.value === "JASPER_REPORT") {
		    $('#container-allegati-template-nativo-disciplinare').addClass("hidden");
			$('#container-allegati-template-jasper-disciplinare').removeClass("hidden");

			var conteggioJasperPresenti = $("#<portlet:namespace />container-upload-allegati-jasper-disciplinare > div").length;

			if(conteggioJasperPresenti==0){
				aggiungiRigaJasperDisciplinare();
			}

			$('#allegatoPrincipaleDisciplinare0')
					.prop("checked", true);
		}

        if(selectObj.value === "NATIVA"){
         	$('#container-allegati-template-jasper-disciplinare').addClass("hidden");
         	$('#container-allegati-template-nativo-disciplinare').removeClass("hidden");
        }

        if(selectObj.value === ""){
            $('#container-allegati-template-jasper-disciplinare').addClass("hidden");
         	$('#container-allegati-template-nativo-disciplinare').addClass("hidden");
        }
	}

    function handleAttachmentsDisciplinareEsecuzione(selectObj) {
        if (selectObj.value === "JASPER_REPORT") {
            $('#container-allegati-template-nativo-disciplinare-esecuzione').addClass("hidden");
            $('#container-allegati-template-jasper-disciplinare-esecuzione').removeClass("hidden");

            var conteggioJasperPresenti = $("#<portlet:namespace />container-upload-allegati-jasper-disciplinare-esecuzione > div").length;

            if(conteggioJasperPresenti==0){
                aggiungiRigaJasperDisciplinare();
            }

            $('#allegatoPrincipaleDisciplinareEsecuzione0')
                .prop("checked", true);
        }

        if(selectObj.value === "NATIVA"){
            $('#container-allegati-template-jasper-disciplinare-esecuzione').addClass("hidden");
            $('#-esecuzionecontainer-allegati-template-nativo-disciplinare-esecuzione').removeClass("hidden");
        }

        if(selectObj.value === ""){
            $('#container-allegati-template-jasper-disciplinare-esecuzione').addClass("hidden");
            $('#container-allegati-template-nativo-disciplinare-esecuzione').addClass("hidden");
        }
    }

