    function eliminaRigaJasperReportDisciplinareEsecuzione(btn){
        var id = $(btn).attr('id').replace('rimuoviJasperDisciplinareEsecuzione','');
        var indexRiga = parseInt(id);
        var checkboxPrincipale = $('#allegatoPrincipaleDisciplinareEsecuzione' + id).is(":checked");
        var countJasperReport = $("#<portlet:namespace />container-upload-allegati-jasper-disciplinare-esecuzione > div").length;

        console.log("valore checkbox: " + checkboxPrincipale);

        if(countJasperReport>1){

            $('#jasperDivDisciplinareEsecuzione' + id).remove();
            shiftRowJasperReportDisciplinareEsecuzione(indexRiga);
            indexJasperReportDisciplinareEsecuzione--;

            if(checkboxPrincipale){
                console.log("effettuare change principale");
                let elemento = $(".checkboxPrincipaleAllegatiDisciplinareEsecuzione").first().prop("checked", true);
                console.log("elemento change : " + elemento);
            }
        }else{

            if(!checkboxPrincipale){
                $('#jasperDivDisciplinareEsecuzione' + id).remove();
                shiftRowJasperReportDisciplinareEsecuzione(indexRiga);
                indexJasperReportDisciplinareEsecuzione--;
            }
        }

        var countJasperReportAfterDelete = $("#<portlet:namespace />container-upload-allegati-jasper-disciplinare-esecuzione > div").length;
        $("#<portlet:namespace />countJasperReportDisciplinareEsecuzione").val(countJasperReportAfterDelete);

        if(countJasperReportAfterDelete > 0){
            var principaleChecked = $('.checkboxPrincipaleAllegatiDisciplinareEsecuzione:checked').length > 0;
            if(!principaleChecked){
                $('.checkboxPrincipaleAllegatiDisciplinareEsecuzione').first().prop("checked", true);
            }
        }
    }

