        List<JournalArticle>      listaArticoliCatalogoBandi = new ArrayList<JournalArticle>();
        List<JournalArticle>      listaArticoliFaqBandi = new ArrayList<JournalArticle>();
        Map<String, List<Layout>> pagineDisponibili          = new HashMap<>();

        Bando  bando                           = null;
