        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_ARTICLE_CATALOGO_BANDI, listaArticoliCatalogoBandi);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_ARTICLE_FAQ_BANDI, listaArticoliFaqBandi);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_URI_PUBBLICHE, pagineDisponibili.get(GestioneBandiFrontendPortletKeys.LISTA_URI_PUBBLICHE));

        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.OPERAZIONI, operazioni);

        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_TIPOLOGIA_BENEFICIARI , TipologiaBeneficiariEnum.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_DIMENSIONI_AZIENDALI  , DimensioneAziendaleEnum.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_TIPOLOGIE_AVVISO      , TipologiaAvvisoEnum.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_TIPOLOGIE_AVVISO      , TipologiaAvvisoEnum.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_RILEVANZA_CODICE_ATECO, CodiceAtecoRilevanzaEnum.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.STATI, listaStatoDomanda);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.STATI_DTO,listaDomandaStatoDTO);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.AUTOCOMPLETE_STATI, JSONFactoryUtil.looseSerialize(listaStatoDomandaAutocomplete));
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.SOTTO_ORGANIZZAZIONI, listaSottoOrganizzazione);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.TERMINI_BANDO, termineBandoTmpList);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.TERMINI_BANDO_VARIABILI, termineBandoVariabiliTmpList);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.CRITERI_VALUTAZIONE_DOMANDA, listaCriterioValutazione);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.REQUISITI_DOMANDA, listaRequisitoDomandaBandoMod);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.VALORE_REQUISITO, mapValoreRequisitoDomanda);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.BUDGETS_BANDO, budgetsBando);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_RANGE_IMPORTI_VALUTAZIONE, rangeImportiValutazione);
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_ENUM_FASI_ASSEGNABILITA_IMPORTO , FasiAssegnabilitaImportoEnum.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_CLIENT_PROTOCOLLAZIONE, TipoProtocolloClient.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.LISTA_TIPO_GESTIONE_PRIORITA, TipoGestionePriorita.values());
        List<String> tipologiaBandoEnums = TipologiaBandoEnum.getByAssegnazioneBudget(true).stream().map(Enum::name).collect(Collectors.toList());
        try {
            renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.TIPOLOGIA_BANDO_ASSEGNAZIONE_BUDGET, new ObjectMapper().writeValueAsString(tipologiaBandoEnums));
        } catch (JsonProcessingException e) {
            _log.error("Errore nella creazione della lista di tipologie :: ", e);
        }

        List<TemplatePdf> templatesPdf;
        if (idBando > 0) {
            try {
                templatesPdf = templatePdfLocalService.getTemplatePdfByBandoId(idBando);

                if (templatesPdf != null && !templatesPdf.isEmpty()) {
                    Map<Long, FileEntry> templatePdfFileEntriesMap = templatePdfFileService.getTemplatePdfFileEntriesMap(templatesPdf);
                    for (TemplatePdf templatePdf : templatesPdf) {
                        if (templatePdf != null) {
                            FileEntry fileEntry = templatePdfFileEntriesMap.get(templatePdf.getTemplatePdfId());
                            if (fileEntry != null) {
                                templatePdf.setNomeFile(fileEntry.getFileName());
                            }
                        }
                    }
                }

                Map<String, TemplatePdf> nativeTemplates = new HashMap<>();

                for (TemplatePdf template : templatesPdf) {
                    String tipoTemplate = template.getTipoTemplate();
                    String codice = template.getCodice();

                    if ("FREEMARKER".equalsIgnoreCase(tipoTemplate)) {
                        nativeTemplates.put(codice, template);
                    }
                }

                renderRequest.setAttribute("templateNativoIstanza",
                        nativeTemplates.get(CodiceTemplatePdf.ISTANZA.name()));
                renderRequest.setAttribute("templateNativoSoccorsoIstruttorio",
                        nativeTemplates.get(CodiceTemplatePdf.RICHIESTA_SOCCORSO_ISTRUTTORIO.name()));
                renderRequest.setAttribute("templateNativoIstanzaSoccorsoIstruttorio",
                        nativeTemplates.get(CodiceTemplatePdf.ISTANZA_SOCCORSO_ISTRUTTORIO.name()));
                renderRequest.setAttribute("templateNativoIstanzaAnnullamento",
                        nativeTemplates.get(CodiceTemplatePdf.ISTANZA_ANNULLAMENTO.name()));
                renderRequest.setAttribute("templateNativoDisciplinare",
                        nativeTemplates.get(CodiceTemplatePdf.DISCIPLINARE.name()));
                renderRequest.setAttribute("templateNativoPrimaDomandaAnticipo",
                        nativeTemplates.get(CodiceTemplatePdf.PRIMA_DOMANDA_ANTICIPO.name()));
                renderRequest.setAttribute("templateNativoSecondaDomandaAnticipo",
                        nativeTemplates.get(CodiceTemplatePdf.SECONDA_DOMANDA_ANTICIPO.name()));
                renderRequest.setAttribute("templateNativoEsitoDomanda",
                        nativeTemplates.get(CodiceTemplatePdf.ESITO_DOMANDA.name()));

                listaTemplatePdfIstanza = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(bando.getBandoId(), TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.ISTANZA.name());
                listaTemplatePdfSoccorsoIstruttorio = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(bando.getBandoId(), TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.RICHIESTA_SOCCORSO_ISTRUTTORIO.name());
                listaTemplatePdfIstanzaSoccorsoIstruttorio = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(bando.getBandoId(), TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.ISTANZA_SOCCORSO_ISTRUTTORIO.name());
                listaTemplatePdfIstanzaAnnullamento = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(bando.getBandoId(), TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.ISTANZA_ANNULLAMENTO.name());
                listaTemplatePdfDisciplinare = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(bando.getBandoId(), TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.DISCIPLINARE.name());
                listaTemplatePdfPrimaDomandaAnticipo = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(bando.getBandoId(), TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.PRIMA_DOMANDA_ANTICIPO.name());
                listaTemplatePdfSecondaDomandaAnticipo = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(bando.getBandoId(), TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.SECONDA_DOMANDA_ANTICIPO.name());
                listaTemplatePdfEsitoDomanda = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(bando.getBandoId(), TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.ESITO_DOMANDA.name());

                renderRequest.setAttribute("listaTemplatePdfIstanza", listaTemplatePdfIstanza);
                renderRequest.setAttribute("listaTemplatePdfSoccorsoIstruttorio", listaTemplatePdfSoccorsoIstruttorio);
                renderRequest.setAttribute("listaTemplatePdfIstanzaSoccorsoIstruttorio", listaTemplatePdfIstanzaSoccorsoIstruttorio);
                renderRequest.setAttribute("listaTemplatePdfIstanzaAnnullamento", listaTemplatePdfIstanzaAnnullamento);
                renderRequest.setAttribute("listaTemplatePdfDisciplinare", listaTemplatePdfDisciplinare);
                renderRequest.setAttribute("listaTemplatePdfPrimaDomandaAnticipo", listaTemplatePdfPrimaDomandaAnticipo);
                renderRequest.setAttribute("listaTemplatePdfSecondaDomandaAnticipo", listaTemplatePdfSecondaDomandaAnticipo);
                renderRequest.setAttribute("listaTemplatePdfEsitoDomanda", listaTemplatePdfEsitoDomanda);

            } catch (Exception e) {
                _log.error("Error retrieving template information: " + e.getMessage(), e);

                renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.TEMPLATES_PDF_INFO, "[]");
                renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.TEMPLATES_PDF_LIST, new ArrayList<>());

                renderRequest.setAttribute("templateNativoIstanza", null);
                renderRequest.setAttribute("templateNativoSoccorsoIstruttorio", null);
                renderRequest.setAttribute("templateNativoIstanzaSoccorsoIstruttorio", null);
                renderRequest.setAttribute("templateNativoIstanzaAnnullamento", null);
                renderRequest.setAttribute("templateNativoDisciplinare", null);
                renderRequest.setAttribute("templateNativoPrimaDomandaAnticipo", null);
                renderRequest.setAttribute("templateNativoSecondaDomandaAnticipo", null);
                renderRequest.setAttribute("templateNativoEsitoDomanda", null);

                renderRequest.setAttribute("listaTemplatePdfIstanza", new ArrayList<>());
                renderRequest.setAttribute("listaTemplatePdfSoccorsoIstruttorio", new ArrayList<>());
                renderRequest.setAttribute("listaTemplatePdfIstanzaSoccorsoIstruttorio", new ArrayList<>());
                renderRequest.setAttribute("listaTemplatePdfIstanzaAnnullamento", new ArrayList<>());
                renderRequest.setAttribute("listaTemplatePdfDisciplinare", new ArrayList<>());
                renderRequest.setAttribute("listaTemplatePdfPrimaDomandaAnticipo", new ArrayList<>());
                renderRequest.setAttribute("listaTemplatePdfSecondaDomandaAnticipo", new ArrayList<>());
                renderRequest.setAttribute("listaTemplatePdfEsitoDomanda", new ArrayList<>());
            }
        } else {
            renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.TEMPLATES_PDF_INFO, "[]");
            renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.TEMPLATES_PDF_LIST, new ArrayList<>());

            renderRequest.setAttribute("templateNativoIstanza", null);
            renderRequest.setAttribute("templateNativoSoccorsoIstruttorio", null);
            renderRequest.setAttribute("templateNativoIstanzaSoccorsoIstruttorio", null);
            renderRequest.setAttribute("templateNativoIstanzaAnnullamento", null);
            renderRequest.setAttribute("templateNativoDisciplinare", null);
            renderRequest.setAttribute("templateNativoPrimaDomandaAnticipo", null);
            renderRequest.setAttribute("templateNativoSecondaDomandaAnticipo", null);
            renderRequest.setAttribute("templateNativoEsitoDomanda", null);

            renderRequest.setAttribute("listaTemplatePdfIstanza", new ArrayList<>());
            renderRequest.setAttribute("listaTemplatePdfSoccorsoIstruttorio", new ArrayList<>());
            renderRequest.setAttribute("listaTemplatePdfIstanzaSoccorsoIstruttorio", new ArrayList<>());
            renderRequest.setAttribute("listaTemplatePdfIstanzaAnnullamento", new ArrayList<>());
            renderRequest.setAttribute("listaTemplatePdfDisciplinare", new ArrayList<>());
            renderRequest.setAttribute("listaTemplatePdfPrimaDomandaAnticipo", new ArrayList<>());
            renderRequest.setAttribute("listaTemplatePdfSecondaDomandaAnticipo", new ArrayList<>());
        }

        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.BANDO_TIPOLOGIA_ENTE_VALUES, TipologiaEnteBando.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.BANDO_UTENTE_DESTINATARIO_VALUES, UtenteDestinatario.values());
        renderRequest.setAttribute(GestioneBandiFrontendPortletKeys.CONTESTI, Contesto.values());

        boolean isGestoreIntegrazioneDati = gestioneBandiMiddlewareService.isGestoreIntegrazioneDati(themeDisplay);
        if (isGestoreIntegrazioneDati) {
            try {
                List<TipologiaServizioEsternoIntegrazioni> listaTipologieServizioEsterno = tipologiaServizioEsternoIntegrazioniLocalService.getTipologiaServizioEsternoIntegrazionis(QueryUtil.ALL_POS, QueryUtil.ALL_POS);
                List<ServizioEsterno> listaServiziEsterniConfigurati = recuperaServiziEsterni(idBando);

                ObjectMapper objectMapper = new ObjectMapper();
                String serviziEsterniJson = objectMapper.writeValueAsString(listaServiziEsterniConfigurati);

                renderRequest.setAttribute("serviziEsterniConfiguratiJson", serviziEsterniJson);
                renderRequest.setAttribute("serviziEsterni", listaTipologieServizioEsterno);
                renderRequest.setAttribute("integrazioniDatiChiavi", Arrays.asList(IntegrazioniDatiChiave.values()));
            } catch (Exception e) {
                _log.error("Errore durante il caricamento delle integrazioni dati: " + e.getMessage(), e);
                renderRequest.setAttribute("serviziEsterniConfiguratiJson", "[]");
                renderRequest.setAttribute("serviziEsterni", Collections.emptyList());
                renderRequest.setAttribute("integrazioniDatiChiavi", Collections.emptyList());
            }
        }
        renderRequest.setAttribute("isGestoreIntegrazioneDati", isGestoreIntegrazioneDati);

        return GestioneBandiFrontendPortletKeys.JSP_AGGIUNGI_MODIFICA_BANDO;
    }

    private List<ServizioEsterno> recuperaServiziEsterni(long bandoId) {
        if (bandoId <= 0) {
            return Collections.emptyList();
        }
        List<BandoIntegrazioniDati> listaChiaviValori = bandoIntegrazioniDatiLocalService.dynamicQuery(
            bandoIntegrazioniDatiLocalService.dynamicQuery()
                .add(com.liferay.portal.kernel.dao.orm.RestrictionsFactoryUtil.eq("bandoId", bandoId))
        );
        Map<Long, List<BandoIntegrazioniDati>> gruppi = listaChiaviValori.stream()
            .collect(Collectors.groupingBy(BandoIntegrazioniDati::getTipologiaServizioEsternoIntegrazioniId));
        return gruppi.entrySet().stream().map(this::mappaServizioEsterno).collect(Collectors.toList());
    }

    private ServizioEsterno mappaServizioEsterno(Entry<Long, List<BandoIntegrazioniDati>> gruppo) {
        List<ChiaveValore> listaChiavi = gruppo.getValue().stream().map(this::mappaChiaveValore).collect(Collectors.toList());
        ServizioEsterno servizioEsterno = new ServizioEsterno();
        servizioEsterno.setTipologiaId(gruppo.getKey());
        servizioEsterno.setChiavi(listaChiavi);
        return servizioEsterno;
    }

    private ChiaveValore mappaChiaveValore(BandoIntegrazioniDati dato) {
        String valoreDecifrato;
        try {
            valoreDecifrato = gestioneBandiMiddlewareService.decrypt(dato.getValore());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        ChiaveValore chiaveValore = new ChiaveValore();
        chiaveValore.setChiave(dato.getChiave());
        chiaveValore.setValore(valoreDecifrato);
        return chiaveValore;
    }
}

