if(Validator.isNotNull(tipoGenerazionePDFDisciplinare)){
    if (tipoGenerazionePDFDisciplinare.equalsIgnoreCase(TipoGenerazionePDF.JASPER_REPORT.name())) {
        gestioneBandiMiddlewareService.deleteTemplatePdfBando(idBando, TipoTemplate.FREEMARKER.name(), CodiceTemplatePdf.DISCIPLINARE.name());

        List<Long> listaReportDaMantenere = new ArrayList<Long>();
        TemplatePdf templateCaricato = null;
        TemplatePdf templatePrincipale = null;
        if (Validator.isNotNull(rowIndexesDisciplinare)) {
            long reportIdNuovoPrincipale = 0;

            if (idBando > 0) {
                templatePrincipale = gestioneBandiMiddlewareService.recuperaTemplatePdfPrincipale(idBando, CodiceTemplatePdf.DISCIPLINARE.name());
            }

            int principaleIndex = -1;
            for (int i = 0; i < Long.valueOf(rowIndexesDisciplinare); i++) {
                boolean principale = ParamUtil.getBoolean(actionRequest, "allegatoPrincipaleDisciplinare" + i);
                if (principale) {
                    principaleIndex = i;
                    break;
                }
            }

            if (principaleIndex >= 0) {
                int i = principaleIndex;
                boolean principale = true;
                long reportId = ParamUtil.getLong(actionRequest, "idAllegatoJasperDisciplinare" + i);
                File file = uploadPortletRequest.getFile("jasperReportFileDisciplinare" + i);
                String nomeFile = uploadPortletRequest.getFileName("jasperReportFileDisciplinare" + i);
                if (Validator.isNotNull(nomeFile)) {
                    nomeFile = normalizeTemplateFileName(nomeFile, CodiceTemplatePdf.DISCIPLINARE.name());
                }

                if (Validator.isNotNull(file) && Validator.isNotNull(nomeFile)) {
                    if (!nomeFile.toLowerCase().endsWith(".jrxml")) {
                        auditService.saveErrorLog(actionRequest, "Formato file non valido per template Jasper: " + nomeFile);
                        SessionErrors.add(actionRequest, GestioneBandiFrontendPortletKeys.SESSION_ERROR_FILE_EXTENSION);
                        _log.error("File caricato non è un .jrxml: " + nomeFile);
                        renderParameters.setValue("mvcRenderCommandName", GestioneBandiFrontendPortletKeys.DETTAGLIO_NUOVO_RENDER_COMMAND);
                        return;
                    }
                }

                if (Validator.isNotNull(file)) {
                    templateCaricato = gestioneBandiMiddlewareService.caricaTemplatePdf(file, CodiceTemplatePdf.DISCIPLINARE.name(), nomeFile, principale, idBando, reportId, i, userFullName, userId,
                            siteGroupId, companyId);

                    if (Validator.isNotNull(templateCaricato)) {
                        listaReportDaMantenere.add(templateCaricato.getTemplatePdfId());
                    }
                } else if (reportId > 0) {
                    listaReportDaMantenere.add(reportId);
                }

                if (Validator.isNotNull(templatePrincipale)) {
                    if (templatePrincipale.getTemplatePdfId() != reportId) {
                        if (reportId == 0) {
                            reportIdNuovoPrincipale = templateCaricato.getTemplatePdfId();
                        }
                        else {
                            reportIdNuovoPrincipale = reportId;
                        }
                    }
                } else {
                    if (reportId == 0) {
                        reportIdNuovoPrincipale = templateCaricato.getTemplatePdfId();
                    }
                    else {
                        reportIdNuovoPrincipale = reportId;
                    }
                }
            }

            for (int i = 0; i < Long.valueOf(rowIndexesDisciplinare); i++) {
                if (i == principaleIndex) {
                    continue;
                }

                boolean principale = false;
                long reportId = ParamUtil.getLong(actionRequest, "idAllegatoJasperDisciplinare" + i);
                File file = uploadPortletRequest.getFile("jasperReportFileDisciplinare" + i);
                String nomeFile = uploadPortletRequest.getFileName("jasperReportFileDisciplinare" + i);
                if (Validator.isNotNull(nomeFile)) {
                    nomeFile = normalizeTemplateFileName(nomeFile, CodiceTemplatePdf.DISCIPLINARE.name());
                }

                if (Validator.isNotNull(file) && Validator.isNotNull(nomeFile)) {
                    if (!nomeFile.toLowerCase().endsWith(".jrxml")) {
                        auditService.saveErrorLog(actionRequest, "Formato file non valido per template Jasper: " + nomeFile);
                        SessionErrors.add(actionRequest, GestioneBandiFrontendPortletKeys.SESSION_ERROR_FILE_EXTENSION);
                        _log.error("File caricato non è un .jrxml: " + nomeFile);
                        renderParameters.setValue("mvcRenderCommandName", GestioneBandiFrontendPortletKeys.DETTAGLIO_NUOVO_RENDER_COMMAND);
                        return;
                    }
                }

                if (Validator.isNotNull(file)) {
                    templateCaricato = gestioneBandiMiddlewareService.caricaTemplatePdf(file, CodiceTemplatePdf.DISCIPLINARE.name(), nomeFile, principale, idBando, reportId, i, userFullName, userId,
                            siteGroupId, companyId);

                    if (Validator.isNotNull(templateCaricato)) {
                        listaReportDaMantenere.add(templateCaricato.getTemplatePdfId());
                    }
                } else if (reportId > 0) {
                    listaReportDaMantenere.add(reportId);
                }
            }

            if (reportIdNuovoPrincipale > 0 && Validator.isNotNull(templatePrincipale)) {
                gestioneBandiMiddlewareService.aggiornaPrincipaleTemplatePdf(templatePrincipale, reportIdNuovoPrincipale, CodiceTemplatePdf.DISCIPLINARE.name());
            }

            gestioneBandiMiddlewareService.deleteTemplatePdf(listaReportDaMantenere, idBando, CodiceTemplatePdf.DISCIPLINARE.name());
        }
    }else if (tipoGenerazionePDFDisciplinare.equalsIgnoreCase(TipoGenerazionePDF.NATIVA.name())) {
        gestioneBandiMiddlewareService.deleteTemplatePdfBando(idBando, TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.DISCIPLINARE.name());
        InputStream allegato = uploadPortletRequest.getFileAsStream("templateNativoFileDisciplinare");
        long templatePdfId = ParamUtil.getLong(actionRequest, "idAllegatoTemplateNativoDisciplinare");

        if (Validator.isNotNull(allegato)) {
            List<TemplatePdf> templateNativiDisciplinare = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(idBando, TipoTemplate.FREEMARKER.name(), CodiceTemplatePdf.DISCIPLINARE.name());

            if(ListUtil.isNotNull(templateNativiDisciplinare) && ListUtil.isNotEmpty(templateNativiDisciplinare)){
                if(templatePdfId == 0 && templateNativiDisciplinare.size() == 1) {
                    templatePdfId = templateNativiDisciplinare.get(0).getTemplatePdfId();
                } else {
                    gestioneBandiMiddlewareService.deleteTemplatePdfBando(idBando, TipoTemplate.FREEMARKER.name(), CodiceTemplatePdf.DISCIPLINARE.name());
                    templatePdfId = 0;
                }
            }

            String nomeFile = uploadPortletRequest.getFileName("templateNativoFileDisciplinare");
            if (Validator.isNotNull(nomeFile)) {
                nomeFile = normalizeTemplateFileName(nomeFile, CodiceTemplatePdf.DISCIPLINARE.name());
            }
            if (Validator.isNotNull(nomeFile) && !nomeFile.toLowerCase().endsWith(".ftl")) {
                auditService.saveErrorLog(actionRequest, "Formato file non valido per template Nativo: " + nomeFile);
                SessionErrors.add(actionRequest, GestioneBandiFrontendPortletKeys.SESSION_ERROR_FILE_EXTENSION);
                _log.error("File caricato non è un .ftl: " + nomeFile);
                renderParameters.setValue("mvcRenderCommandName", GestioneBandiFrontendPortletKeys.DETTAGLIO_NUOVO_RENDER_COMMAND);
                return;
            }
            if (Validator.isNotNull(nomeFile)) {
                gestioneBandiMiddlewareService.caricaTemplateNativoPdf(allegato, CodiceTemplatePdf.DISCIPLINARE.name(), nomeFile, idBando, templatePdfId, null,
                        userFullName, userId, siteGroupId, companyId);
            }
        } else {
            if (templatePdfId == 0) {
                List<TemplatePdf> existingTemplates = gestioneBandiMiddlewareService.recuperaTemplatePdfAggiuntivi(
                        idBando, TipoTemplate.FREEMARKER.name(), CodiceTemplatePdf.DISCIPLINARE.name());
                if (ListUtil.isNotEmpty(existingTemplates)) {
                    gestioneBandiMiddlewareService.deleteTemplatePdfBando(idBando, TipoTemplate.FREEMARKER.name(),
                            CodiceTemplatePdf.DISCIPLINARE.name());
                }
                gestioneBandiMiddlewareService.caricaTemplateNativoPdf(null, CodiceTemplatePdf.DISCIPLINARE.name(),
                        null, idBando, 0, null, userFullName, userId, siteGroupId, companyId);
            }
        }
    } else {
        gestioneBandiMiddlewareService.deleteTemplatePdfBando(idBando, TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.DISCIPLINARE.name());
        gestioneBandiMiddlewareService.deleteTemplatePdfBando(idBando, TipoTemplate.FREEMARKER.name(), CodiceTemplatePdf.DISCIPLINARE.name());
    }
} else {
    gestioneBandiMiddlewareService.deleteTemplatePdfBando(idBando, TipoTemplate.JASPER_REPORT.name(), CodiceTemplatePdf.DISCIPLINARE.name());
    gestioneBandiMiddlewareService.deleteTemplatePdfBando(idBando, TipoTemplate.FREEMARKER.name(), CodiceTemplatePdf.DISCIPLINARE.name());
}

